  span: ts.TextSpan,
  format: ts.SemanticClassificationFormat | undefined,
): ts.Classifications;

// PerfPhase enum (packages/compiler-cli/src/ngtsc/perf/src/api.ts)
export enum PerfPhase {
  // ...existing values...
  LSApplyRefactoring,

